## chamadas
- bash (intenção: Finding keyed DOM attributes | comando: cd /home/one/projects/one/rich-editor-auy/ref/lexical/packages/lexical && grep -n "data-lexical\|__lexicalKey\|setNodeKeyOnDOMNode" src/LexicalUtils.ts src/LexicalReconciler.ts | head -25)
- bash (intenção: Running light perf probe | comando: cd /tmp/lexical-probe && cat > perf.mjs <<'EOF'
import {$createParagraphNode, $createTextNode, $getRoot, createEditor} from 'lexical';
const mk = n => { const ed = createEditor({namespace:'p'}); ed.update(()=>{ const r=$getRoot(); const ps=[]; for(let i=0;i<n;i++) ps.push($createParagraphNode().append($createTextNode('paragraph '+i+' lorem ipsum dolor sit amet'))); r.append(...ps); }, {discrete:true}); return ed; };
for (const n of [100, 1000, 5000]) {
  const t0 = performance.now(); const ed = mk(n); const t1 = performance.now();
  const t2 = performance.now(); const json = ed.getEditorState().toJSON(); const t3 = performance.now();
  const s = JSON.stringify(json); const t4 = performance.now();
  console.log(`n=${n} build=${(t1-t0).toFixed(1)}ms toJSON=${(t3-t2).toFixed(1)}ms stringify=${(t4-t3).toFixed(1)}ms jsonBytes=${s.length}`);
}
// typing cost: 200 sequential edits on a 1000-paragraph doc
const ed = mk(1000);
const t0=performance.now();
for (let i=0;i<200;i++) ed.update(()=>{ const p=$getRoot().getChildAtIndex(i%1000); if(p){const t=p.getFirstChild(); if(t) t.setTextContent('x'+i);} }, {discrete:true});
const t1=performance.now();
console.log(`200 discrete updates on 1000 paragraphs: ${(t1-t0).toFixed(1)}ms total (${((t1-t0)/200).toFixed(2)}ms each)`);
EOF
node perf.mjs 2>&1 | tail -10)

